export const ftwspScreenPx = /* @__PURE__ */ screenFn(B, DpQualifier.WIDTH, KIND_SP, true);

// ── Builder (Android `DimenFit` / `FitSp`). ───────────────────────────
/** Custom-dimension builder for the fit strategy. */
export class DimenFit extends DimenBuilder {
  get ftsdp(): number { return this.sdp; }
  get ftsdpPx(): number { return this.sdpPx; }
  get ftssp(): number { return this.ssp; }
  get ftsspPx(): number { return this.sspPx; }
  get ftsem(): number { return this.sem; }
  get ftsemPx(): number { return this.semPx; }
  get fthdp(): number { return this.hdp; }
  get fthdpPx(): number { return this.hdpPx; }
  get fthsp(): number { return this.hsp; }
  get fthspPx(): number { return this.hspPx; }
  get fthem(): number { return this.hem; }
  get fthemPx(): number { return this.hemPx; }
  get ftwdp(): number { return this.wdp; }
  get ftwdpPx(): number { return this.wdpPx; }
  get ftwsp(): number { return this.wsp; }
  get ftwspPx(): number { return this.wspPx; }
  get ftwem(): number { return this.wem; }
  get ftwemPx(): number { return this.wemPx; }
}
/** Starts a builder: `fitDp(16).screen(UiModeType.TELEVISION, 40).ftsdp`. */
export const fitDp = (value: number): DimenFit => new DimenFit(B, value);
/** Text builder (same class; read `.ftssp` / `.ftsem`). */
export const fitSp = (value: number): DimenFit => new DimenFit(B, value);
